7aedb3ed-1dda-4add-884a-c4e53ca706c8	4ff0e0ff-fab2-423e-a59c-b9de4674a84f	\N	2	features	\N	<section class="features-section" data-component="features">\n    <div class="features-container">\n        <h2>What Sets Us Apart in Wholesale Fuel Distribution</h2>\n        <p class="features-subtitle">We handle the logistics, pricing, and reliability so your operation never misses a beat. Here's what you can count on when you work with us.</p>\n        <div class="features-grid">\n            \n            <div class="feature-item">\n                <div class="feature-icon"><i data-lucide="truck"></i></div>\n                <h3>Reliable Bulk Fuel Delivery</h3>\n                <p>Scheduled and on-demand delivery for gas stations, fleet depots, and industrial facilities. We coordinate logistics to keep your tanks full and your operation running without interruption.</p>\n            </div>\n            \n            <div class="feature-item">\n                <div class="feature-icon"><i data-lucide="dollar-sign"></i></div>\n                <h3>Transparent Wholesale Pricing</h3>\n                <p>No hidden fees, no confusing surcharges. Our pricing reflects real market conditions, and we'll walk you through exactly how your rate is structured so you always know what you're paying and why.</p>\n            </div>\n            \n            <div class="feature-item">\n                <div class="feature-icon"><i data-lucide="zap"></i></div>\n                <h3>Natural Gas Supply</h3>\n                <p>Wholesale natural gas supply for commercial and industrial buyers who need consistent volume and dependable contracts. We work with facilities that can't afford gaps in their energy supply.</p>\n            </div>\n            \n            <div class="feature-item">\n                <div class="feature-icon"><i data-lucide="shield"></i></div>\n                <h3>Supply Continuity You Can Plan Around</h3>\n                <p>We maintain supplier relationships and distribution infrastructure specifically to protect against the disruptions that catch smaller distributors off guard. Your supply chain stays intact when market conditions shift.</p>\n            </div>\n            \n            <div class="feature-item">\n                <div class="feature-icon"><i data-lucide="clipboard"></i></div>\n                <h3>Flexible Contract Options</h3>\n                <p>Whether you need spot purchases or long-term supply agreements, we structure contracts around your volume requirements and budget cycles — not the other way around.</p>\n            </div>\n            \n            <div class="feature-item">\n                <div class="feature-icon"><i data-lucide="users"></i></div>\n                <h3>Dedicated Account Support</h3>\n                <p>You work with people who know the fuel industry, not a rotating call center. When you have a question about your delivery, your pricing, or your contract, you get a straight answer from someone who understands the business.</p>\n            </div>\n            \n        </div>\n    </div>\n</section>\n<style>\n/* Layout only - colors inherited from global CSS */\n.features-section {\n    padding: var(--spacing-section, 5rem 2rem);\n}\n.features-container {\n    max-width: var(--container-max-width, 1200px);\n    margin: 0 auto;\n}\n.features-section h2 {\n    text-align: center;\n    margin-bottom: 1rem;\n}\n.features-subtitle {\n    text-align: center;\n    max-width: 600px;\n    margin: 0 auto 3rem;\n}\n.features-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));\n    gap: 2rem;\n}\n.feature-item {\n    text-align: center;\n    padding: 2rem;\n}\n.feature-icon {\n    width: 48px;\n    height: 48px;\n    margin: 0 auto 1rem;\n    color: var(--color-accent, #0f3460);\n}\n.feature-icon svg {\n    width: 100%;\n    height: 100%;\n}\n.feature-item h3 {\n    margin-bottom: 1rem;\n}\n.feature-item p {\n    margin: 0;\n}\n@media (max-width: 768px) {\n